func (h hooked) Call(ctx context.Context, c agent.Call) (agent.Result, error) {
	name := h.Tool.Spec().Name
	orig := c.Input // what the caller sent (after_call's rules read it)
	var in map[string]any
	_ = json.Unmarshal(c.Input, &in)
	str := func(k string) string { s, _ := in[k].(string); return s }
	var draft draftReq
	var rq reqText
	var preUse agent.Usage // spent before the subagent ran (check_deviation's requirement check)
	var held agent.Grant   // kept from the subagent for Go's calls after it (draft_section's figure reader)
	switch name {
	case "extract_facts":
		if str("issueId") == "" { // the plan's issues: each finding names the one it bears on (bench5 SEC: 896 findings, most on none)
			issues, err := load[Issue](ctx, h.e, c.TaskID, kIssue)
			if err != nil {
				return agent.Result{}, err
			}
			only, part := ctx.Value(issuesKey{}).([]string) // a page read again for the issues added since: only those
			var list []map[string]string
			for _, is := range issues {
				if !part || slices.Contains(only, is.ID) {
					list = append(list, map[string]string{"id": is.ID, "question": is.Question})
				}
			}
			if len(list) > 0 {
				in["issues"] = list
			}
		}
		if str("documentId") != "" && str("sectionId") != "" {
			off, _ := in["offset"].(float64)
			if str("through") != "" {
				text, ok := h.e.runText(ctx, c.DocumentIDs, str("documentId"), str("sectionId"), str("through"))
				if !ok || off != 0 {
					return agent.Result{}, agent.Fail(fmt.Sprintf("extract_facts: through must be a top-level section at or after sectionId, the run at most %d tokens, with offset 0 or null", docs.MaxSectionTokens))
				}
				in["sectionText"], in["truncated"], in["next"] = text, false, 0
			} else if p, err := h.e.docs.Section(ctx, c.DocumentIDs, str("documentId"), str("sectionId"), int(off), sweepTokens); err == nil {
				in["sectionText"], in["truncated"], in["next"] = p.Text, p.Truncated, p.Next
				if p.Header != "" { // a later page of a table: its columns, by reference to the header row
					in["header"] = p.Header
				}
			}
		}
	case "analyze_issue":
		for _, p := range packsFor(ctx, str("jurisdiction"), "") {
			in["packText"] = str("packText") + "\n\n" + p.Body
		}
	case "check_deviation":
		var err error
		if rq, err = h.e.quotedRequirement(ctx, c); err != nil {
			return agent.Result{}, err
		}
		in["requirement"] = rq.Joined()
		in["requirementContext"] = rq.Context()                                // what it judges against: the requirement with what governs it
		var su agent.Usage                                                     // the passages' query embedding, metered (lab-r4 verifier L3)
		in["reviewedPassages"], su = h.e.reviewedPassages(ctx, c, rq.Joined()) // bench4, trust: every call spent its five turns searching and checking quotes
		pre := agent.NewBudget(c.Budget.Calls, max(0, c.Budget.USD-su.USD), 0) // the requirement's check comes out of the grant first (bench5: unfunded checks dropped real deviations)
		if rq.Check, rq.CheckWhy, err = h.e.checkSection(ctx, h.rt, pre, rq); err != nil {
			u := pre.Spent()
			u.Add(su)
			return agent.Result{Usage: u}, err
		}
		preUse = pre.Spent()
		preUse.Add(su)
		c.Budget = agent.Grant{Calls: max(0, c.Budget.Calls-preUse.Calls), USD: max(0, c.Budget.USD-preUse.USD)}
		if rq.Check != nil && rq.Check.Answer == "no" { // nothing to compare with: the document does not require it
			return agent.Result{Usage: preUse}, agent.Fail(fmt.Sprintf("check_deviation: an independent reading of %s around the requirement found that it does not impose the requirement as quoted (negated or overridden): %s. Quote the requirement together with what governs it (its lead-in, exception or override), as the document states what it requires, and call again",
				rq.DocName, fenceText.Replace(rq.Check.Reason)))
		}
	case "draft_section":
		var err error
		if draft, err = h.e.draftRequest(ctx, c.TaskID, c.DocumentIDs, str("issueId"), c.Input); err != nil {
			return agent.Result{}, err
		}
		in = draft.request
	}
	if r := readerReserve(ctx, h.rt); goTurns(name) > 0 && ctx.Value(readQueueKey{}) == nil && c.Budget.Calls > r.Calls && (r.USD == 0 || c.Budget.USD > r.USD) { // the figure reader of its answer, held back from the subagent (lab-r4 r5 L4); a sweep's visit reads nothing itself (readFindings)
		held, c.Budget = r, agent.Grant{Calls: c.Budget.Calls - r.Calls, USD: c.Budget.USD - r.USD}
	}
	c.Input, _ = json.Marshal(in)
	res, err := h.Tool.Call(ctx, c)
	res.Usage.Add(preUse)
	if err == nil {
		err = awaitTurn(ctx) // a parallel sweep's visit admits in plan order
	}
	if err != nil {
		return res, err
	}
	b := agent.NewBudget(c.Budget.Calls-res.Usage.Calls+preUse.Calls+held.Calls, c.Budget.USD-res.Usage.USD+preUse.USD+held.USD, 0) // c.Budget is already net of preUse and held
	// after_call's rules on the subagent's own answer, before Go records anything from it (#58 r1 H1):
	// blocked, nothing is admitted or saved and the answer is withheld; a sweep's visit is still done
	if v, err := afterHooked(ctx, h.rt, c, name, orig, res.Output, b); err != nil {
		res.Usage.Add(b.Spent())
		return res, err
	} else if v.blocked != "" {
		res.Usage.Add(b.Spent())
		if name == "draft_section" {
			return agent.Result{Usage: res.Usage, Model: res.Model}, agent.Fail("draft_section's draft was withheld and not saved: " + v.blocked)
		}
		out, _ := json.Marshal(hookResult{Findings: []map[string]any{}, Notes: []string{"withheld, nothing admitted: " + v.blocked}})
		return agent.Result{Output: out, Usage: res.Usage, Model: res.Model}, nil
	}
	var out any
	var reward float64
	switch name {
	case "draft_section":
		out, err = h.e.saveSection(ctx, h.rt, c, b, draft, res.Output)
		reward = 1
	case "check_deviation":
		out, reward, err = h.e.deviations(ctx, h.rt, c, b, res, rq)
	default:
		var ans struct {
			Findings                      []draftFinding
			Gaps                          []string
			Rule, Application, Conclusion string
			Authorities                   []struct {
				Cite     string
				InRecord bool
			}
		}
		_ = json.Unmarshal(res.Output, &ans)
		notes := slices.Clone(ans.Gaps)
		for k, v := range map[string]string{"rule": ans.Rule, "application": ans.Application, "conclusion": ans.Conclusion} {
			if v != "" {
				notes = append(notes, k+": "+v)
			}
		}
		slices.Sort(notes)
		for _, a := range ans.Authorities {
			if !a.InRecord {
				notes = append(notes, "authority not in the record (flagged if cited): "+a.Cite)
			}
		}
		out, reward, err = h.e.admit(ctx, h.rt, c, b, held, name, str("issueId"), res.Model, ans.Findings, notes)
		if err == nil && name == "analyze_issue" && strings.TrimSpace(ans.Conclusion) != "" && str("issueId") != "" { // for the issue's drafter (cover.go)
			err = h.e.write(ctx, c.TaskID, kAnalysis, str("issueId"), Analysis{truncate(ans.Rule, 1500), truncate(ans.Application, 3000), truncate(ans.Conclusion, 1000)}, true)
		}
	}
	res.Usage.Add(b.Spent())
	if err != nil {
		return res, err
	}
	res.Output, _ = json.Marshal(out)
	res.Reward = &reward
	return res, nil
}

// admit checks a subagent's findings and records them (G2): every quote through the ladder (the
// finding verifies only when all of them do; otherwise it is quarantined), each value kept only
// when its own quote states it, each relation typed by BELO-lite, near-duplicates merged into the
// first. The reward is the share of quotes that verified.
func (e *Engine) admit(ctx context.Context, rt *agent.Runtime, c agent.Call, b *agent.Budget, reserve agent.Grant, tool, issueID, model string, drafts []draftFinding, notes []string) (hookResult, float64, error) {
	out := hookResult{Findings: []map[string]any{}, Notes: append([]string{}, notes...)}
	all, err := load[Finding](ctx, e, c.TaskID, kFinding)
	if err != nil {
		return out, 0, err
	}
	var plan []Issue
	if tool == "extract_facts" && issueID == "" {
		if plan, err = load[Issue](ctx, e, c.TaskID, kIssue); err != nil {
			return out, 0, err
		}
	}
	scoped := len(plan) > 0
	if only, ok := ctx.Value(issuesKey{}).([]string); ok && scoped { // a page read again: the issues added since
		plan = slices.DeleteFunc(plan, func(is Issue) bool { return !slices.Contains(only, is.ID) })
	}
	quotes, ok, off := 0, 0, 0
	type pending struct {
		f    Finding
		d    draftFinding
		text string
		it   *reading
	}
	var pend []pending
	// the quotes' judges spend all but the figure reader's reserve (lab-r4 r5 L4: the reader is never
	// what they left), unless no finding states a number, when the reader makes no call (r7 L4)
	queue, deferred := ctx.Value(readQueueKey{}).(*readQueue) // a sweep reads its findings together at its end
	numbers := !deferred && slices.ContainsFunc(drafts, func(d draftFinding) bool {
		return len(d.Values) > 0 && len(findingReading(Finding{Finding: analysis.Finding{Claim: d.Claim, Entities: d.Entities}}, d.Quotes, d.Values).ps) > 0
	})
	vb := b
	if rc, ru := b.Remaining(); numbers && reserve.Calls > 0 && rc > reserve.Calls {
		if g, err := b.Grant(rc-reserve.Calls, max(0, ru-reserve.USD), agent.LevelWork); err == nil {
			vb = g
			defer g.Close()
		}
	}
	for _, d := range drafts {
		fi := issueID
		if scoped { // a fact on none of the plan's issues is not admitted
			if fi = deref(d.IssueID); !slices.ContainsFunc(plan, func(is Issue) bool { return is.ID == fi }) {
				off++
				continue
			}
		}
		f := Finding{Finding: analysis.Finding{IssueID: fi, Claim: strings.TrimSpace(d.Claim), Quotes: d.Quotes, Entities: d.Entities}, Severity: "medium", Arm: agent.Arm{Tool: tool, Model: model}}
		var text strings.Builder
		var vq []analysis.Quote
		for _, q := range d.Quotes {
			cit, err := e.verify(ctx, rt, c, vb, tool, q)
			if err != nil {
				return out, 0, err
			}
			f.Citations = append(f.Citations, cit)
			quotes++
			if cit.Method != "none" {
				ok++
				text.WriteString(q.Quote + "\n")
				vq = append(vq, analysis.Quote{DocumentID: cit.DocumentID, Quote: q.Quote, Locator: q.Locator})
			}
		}
		f.Verified = len(f.Citations) > 0 && !slices.ContainsFunc(f.Citations, func(c Citation) bool { return c.Method == "none" })
		pend = append(pend, pending{f, d, text.String(), findingReading(f, vq, d.Values)})
	}
	if vb != b {
		vb.Close() // its unspent part back to the call's grant, for the reader
	}
	var items []*reading // one figure reading for the call's findings (cached by content), out of the call's grant
	for _, p := range pend {
		if len(p.text) > 0 && !deferred && len(p.d.Values) > 0 { // a finding with no typed value is read when a section cites it
			items = append(items, p.it)
		}
	}
	if err := e.readFigures(ctx, rt, c, b, tool, items); err != nil {
		return out, 0, err
	}
	for _, p := range pend {
		f, d := p.f, p.d
		if len(p.text) > 0 && (deferred || len(d.Values) == 0) {
			f.Values, f.Unread = d.Values, true // read later: by the sweep at its end, or when a section cites it
		} else {
			applyReading(&f, d.Values, p.it, p.text)
		}
		f.Relations, _ = analysis.Relations(d.Entities, d.Relations)
		if i := slices.IndexFunc(all, func(x Finding) bool {
			return x.ok() && f.ok() && restated(x, f)
		}); i >= 0 {
			for _, c := range f.Citations {
				if !slices.ContainsFunc(all[i].Citations, func(x Citation) bool { return x.DocumentID == c.DocumentID && x.Quote == c.Quote }) {
					all[i].Citations = append(all[i].Citations, c)
					all[i].Quotes = append(all[i].Quotes, analysis.Quote{DocumentID: c.DocumentID, Quote: c.Quote, Locator: c.Locator})
				}
			}
			for _, n := range f.ValueNotes { // the duplicate's dropped values are the kept finding's (shown with it, disclosed)
				if !slices.Contains(all[i].ValueNotes, n) {
					all[i].ValueNotes = append(all[i].ValueNotes, n)
				}
			}
			if err := e.write(ctx, c.TaskID, kFinding, all[i].FID, all[i], true); err != nil {
				return out, 0, err
			}
			out.Notes = append(out.Notes, "merged into "+all[i].FID+" (an exact duplicate): "+f.Claim)
			for _, n := range f.ValueNotes {
				out.Notes = append(out.Notes, all[i].FID+": "+n)
			}
			continue
		}
		if h, ok := rt.Hooks.(hookRunner); ok { // finding_admitted's rules: quarantine, gate or annotate it
			if _, err := h.findingHooks(ctx, c, b, &f); err != nil {
				return out, 0, err
			}
		}
		f.FID = nextID("F", len(all))
		all = append(all, f)
		if deferred && f.Unread && len(f.Values) > 0 {
			queue.add(f.FID)
		}
		if err := e.write(ctx, c.TaskID, kFinding, f.FID, f, false); err != nil {
			return out, 0, err
		}
		out.Findings = append(out.Findings, admitted(f))
		for _, n := range f.ValueNotes {
			out.Notes = append(out.Notes, f.FID+": "+n)
		}
		if !f.Verified {
			out.Dropped++
		}
	}
	if off > 0 {
		out.Notes = append(out.Notes, fmt.Sprintf("dropped %d %s that named none of the plan's issues", off, plural(off, "finding", "findings")))
	}
	if quotes == 0 {
		return out, map[bool]float64{true: 1, false: 0}[len(drafts) == 0], nil
	}
	return out, float64(ok) / float64(quotes), nil
}

func (h hooked) Call(ctx context.Context, c agent.Call) (agent.Result, error) {
	name := h.Tool.Spec().Name
	orig := c.Input // what the caller sent (after_call's rules read it)
	var in map[string]any
	_ = json.Unmarshal(c.Input, &in)
	str := func(k string) string { s, _ := in[k].(string); return s }
	var draft draftReq
	var rq reqText
	var preUse agent.Usage // spent before the subagent ran (check_deviation's requirement check)
	var held agent.Grant   // kept from the subagent for Go's calls after it (draft_section's figure reader)
	switch name {
	case "extract_facts":
		if str("issueId") == "" { // the plan's issues: each finding names the one it bears on (bench5 SEC: 896 findings, most on none)
			issues, err := load[Issue](ctx, h.e, c.TaskID, kIssue)
			if err != nil {
				return agent.Result{}, err
			}
			only, part := ctx.Value(issuesKey{}).([]string) // a page read again for the issues added since: only those
			var list []map[string]string
			for _, is := range issues {
				if !part || slices.Contains(only, is.ID) {
					list = append(list, map[string]string{"id": is.ID, "question": is.Question})
				}
			}
			if len(list) > 0 {
				in["issues"] = list
			}
		}
		if str("documentId") != "" && str("sectionId") != "" {
			off, _ := in["offset"].(float64)
			if str("through") != "" {
				text, ok := h.e.runText(ctx, c.DocumentIDs, str("documentId"), str("sectionId"), str("through"))
				if !ok || off != 0 {
					return agent.Result{}, agent.Fail(fmt.Sprintf("extract_facts: through must be a top-level section at or after sectionId, the run at most %d tokens, with offset 0 or null", docs.MaxSectionTokens))
				}
				in["sectionText"], in["truncated"], in["next"] = text, false, 0
			} else if p, err := h.e.docs.Section(ctx, c.DocumentIDs, str("documentId"), str("sectionId"), int(off), sweepTokens); err == nil {
				in["sectionText"], in["truncated"], in["next"] = p.Text, p.Truncated, p.Next
				if p.Header != "" { // a later page of a table: its columns, by reference to the header row
					in["header"] = p.Header
				}
			}
		}
	case "analyze_issue":
		for _, p := range packsFor(ctx, str("jurisdiction"), "") {
			in["packText"] = str("packText") + "\n\n" + p.Body
		}
	case "check_deviation":
		var err error
		if rq, err = h.e.quotedRequirement(ctx, c); err != nil {
			return agent.Result{}, err
		}
		in["requirement"] = rq.Joined()
		in["requirementContext"] = rq.Context()                                // what it judges against: the requirement with what governs it
		var su agent.Usage                                                     // the passages' query embedding, metered (lab-r4 verifier L3)
		in["reviewedPassages"], su = h.e.reviewedPassages(ctx, c, rq.Joined()) // bench4, trust: every call spent its five turns searching and checking quotes
		pre := agent.NewBudget(c.Budget.Calls, max(0, c.Budget.USD-su.USD), 0) // the requirement's check comes out of the grant first (bench5: unfunded checks dropped real deviations)
		if rq.Check, rq.CheckWhy, err = h.e.checkSection(ctx, h.rt, pre, rq); err != nil {
			u := pre.Spent()
			u.Add(su)
			return agent.Result{Usage: u}, err
		}
		preUse = pre.Spent()
		preUse.Add(su)
		c.Budget = agent.Grant{Calls: max(0, c.Budget.Calls-preUse.Calls), USD: max(0, c.Budget.USD-preUse.USD)}
		if rq.Check != nil && rq.Check.Answer == "no" { // nothing to compare with: the document does not require it
			return agent.Result{Usage: preUse}, agent.Fail(fmt.Sprintf("check_deviation: an independent reading of %s around the requirement found that it does not impose the requirement as quoted (negated or overridden): %s. Quote the requirement together with what governs it (its lead-in, exception or override), as the document states what it requires, and call again",
				rq.DocName, fenceText.Replace(rq.Check.Reason)))
		}
	case "draft_section":
		var err error
		if draft, err = h.e.draftRequest(ctx, c.TaskID, c.DocumentIDs, str("issueId"), c.Input); err != nil {
			return agent.Result{}, err
		}
		in = draft.request
	}
	if r := readerReserve(ctx, h.rt); goTurns(name) > 0 && ctx.Value(readQueueKey{}) == nil && c.Budget.Calls > r.Calls && (r.USD == 0 || c.Budget.USD > r.USD) { // the figure reader of its answer, held back from the subagent (lab-r4 r5 L4); a sweep's visit reads nothing itself (readFindings)
		held, c.Budget = r, agent.Grant{Calls: c.Budget.Calls - r.Calls, USD: c.Budget.USD - r.USD}
	}
	c.Input, _ = json.Marshal(in)
	res, err := h.Tool.Call(ctx, c)
	res.Usage.Add(preUse)
	if err == nil {
		err = awaitTurn(ctx) // a parallel sweep's visit admits in plan order
	}
	if err != nil {
		return res, err
	}
	b := agent.NewBudget(c.Budget.Calls-res.Usage.Calls+preUse.Calls+held.Calls, c.Budget.USD-res.Usage.USD+preUse.USD+held.USD, 0) // c.Budget is already net of preUse and held
	// after_call's rules on the subagent's own answer, before Go records anything from it (#58 r1 H1):
	// blocked, nothing is admitted or saved and the answer is withheld; a sweep's visit is still done
	if v, err := afterHooked(ctx, h.rt, c, name, orig, res.Output, b); err != nil {
		res.Usage.Add(b.Spent())
		return res, err
	} else if v.blocked != "" {
		res.Usage.Add(b.Spent())
		if name == "draft_section" {
			return agent.Result{Usage: res.Usage, Model: res.Model}, agent.Fail("draft_section's draft was withheld and not saved: " + v.blocked)
		}
		out, _ := json.Marshal(hookResult{Findings: []map[string]any{}, Notes: []string{"withheld, nothing admitted: " + v.blocked}})
		return agent.Result{Output: out, Usage: res.Usage, Model: res.Model}, nil
	}
	var out any
	var reward float64
	switch name {
	case "draft_section":
		out, err = h.e.saveSection(ctx, h.rt, c, b, draft, res.Output)
		reward = 1
	case "check_deviation":
		out, reward, err = h.e.deviations(ctx, h.rt, c, b, res, rq)
	default:
		var ans struct {
			Findings                      []draftFinding
			Gaps                          []string
			Rule, Application, Conclusion string
			Authorities                   []struct {
				Cite     string
				InRecord bool
			}
		}
		_ = json.Unmarshal(res.Output, &ans)
		notes := slices.Clone(ans.Gaps)
		for k, v := range map[string]string{"rule": ans.Rule, "application": ans.Application, "conclusion": ans.Conclusion} {
			if v != "" {
				notes = append(notes, k+": "+v)
			}
		}
		slices.Sort(notes)
		for _, a := range ans.Authorities {
			if !a.InRecord {
				notes = append(notes, "authority not in the record (flagged if cited): "+a.Cite)
			}
		}
		out, reward, err = h.e.admit(ctx, h.rt, c, b, held, name, str("issueId"), res.Model, ans.Findings, notes)
		if err == nil && name == "analyze_issue" && strings.TrimSpace(ans.Conclusion) != "" && str("issueId") != "" { // for the issue's drafter (cover.go)
			err = h.e.write(ctx, c.TaskID, kAnalysis, str("issueId"), Analysis{truncate(ans.Rule, 1500), truncate(ans.Application, 3000), truncate(ans.Conclusion, 1000)}, true)
		}
	}
	res.Usage.Add(b.Spent())
	if err != nil {
		return res, err
	}
	res.Output, _ = json.Marshal(out)
	res.Reward = &reward
	return res, nil
}

// quotedRequirement checks check_deviation's requirement before its subagent runs: the words of a
// controlling document (requirementDocId, one of controllingDocIds), verified like any quote
// (exact or tolerant), and returns where that document has them (placeRequirement: JSON escapes
// undone, a requirement the model joined from several passages placed part by part, in order, in
// one passage) with their context. A fragment is no longer refused: its context carries what
// governs it. A paraphrase (bench: the lead's restatement of the requirement, which the subagent
// then quoted as the source) is refused with the nearest exact passage to copy.
func (e *Engine) quotedRequirement(ctx context.Context, c agent.Call) (reqText, error) {
	var in devInput
	_ = json.Unmarshal(c.Input, &in)
	if !slices.Contains(in.ControllingDocIDs, in.RequirementDocID) {
		return reqText{}, agent.Fail("check_deviation: requirementDocId must be one of controllingDocIds: the controlling document the requirement is quoted from")
	}
	d, err := e.docs.Get(ctx, c.DocumentIDs, in.RequirementDocID)
	if err != nil {
		return reqText{}, agent.Fail("check_deviation: requirementDocId is not one of this task's documents")
	}
	r := reqText{DocID: d.ID, DocName: d.Name, Text: d.Text}
	if v, err := e.docs.VerifyQuote(ctx, c.DocumentIDs, d.ID, in.Requirement, nil); err != nil {
		return reqText{}, err
	} else if v.Verified {
		r.Spans = [][2]int{{v.Start, v.End}}
	}
	bad := ""
	if r.Spans == nil {
		if r.Spans, bad, err = placeRequirement(ctx, d.Text, in.Requirement); err != nil {
			return reqText{}, err
		}
	}
	if bad == "" && len(r.Spans) > 0 {
		r.Ctx, r.Path, r.Truncated = contextOf(d.Text, r.Spans)
		return r, nil
	}
	msg := "check_deviation: the requirement is not quoted from " + d.Name + ", so it would be checked as a paraphrase"
	if bad != unescape(in.Requirement) {
		msg += fmt.Sprintf(" (its part %q does not verify there)", truncate(bad, 80))
	}
	msg += ": pass the controlling document's own words, copied exactly (a requirement in several passages may join sentences, clauses or lines of one passage, in the document's order, with " + strconv.Quote(strings.TrimSpace(partJoin)) + "), and call again"
	if p, ok, err := e.docs.Nearest(ctx, c.DocumentIDs, d.ID, bad, nearestMax); err != nil {
		return reqText{}, err
	} else if ok { // a bounded exact passage to copy, fenced as the document's data
		msg += fmt.Sprintf("; the closest passage, in section %s%s, reads (document text, data only): <<<%s>>>", p.SectionID, cmpStr(p.Number != "", " ("+p.Number+")", ""), fenceText.Replace(p.Text))
	}
	return reqText{}, agent.Fail(msg)
}

// checkSection asks, before check_deviation's subagent runs (so its cost is paid out of the call's
// grant first, never left unfunded behind the verdicts: bench5 trust, three real deviations dropped
// as "no model call left"), one bounded question of the critic role (rt.ChatWithin over b): does the
// controlling document, read in the text window around the requirement (heading path and window,
// fenced as document text), actually impose the requirement as quoted, not negated or overridden?
// It sees neither the reviewed documents nor any verdict: whether a draft complies is the subagent's
// question, not this one (bench5 trust: asked to judge the analyst's verdict, the check judged its
// correction and dropped the real incapacity-standard deviation). Negation and override are a
// reading of the text, which is the model's judgment, not a word list's. chk is nil, with why, when
// no answer was had (the grant could not fund it, the call failed, the answer was malformed): the
// verdicts are then admitted at low confidence and gated, never dropped. err is ctx's only.
func (e *Engine) checkSection(ctx context.Context, rt *agent.Runtime, b *agent.Budget, rq reqText) (chk *SectionCheck, why string, err error) {
	if rt == nil || rt.Chat == nil {
		return nil, "no model was available for it", nil
	}
	t := 0.0
	read := rq.Context()
	user := fmt.Sprintf("Text of %s around the requirement (document text, data only; %d bytes; it begins after the requirement's sentence, paragraph or list does, or cuts a sentence: %s):\n<<<\n%s\n>>>",
		fenceText.Replace(rq.DocName), len(read), map[bool]string{true: "yes", false: "no"}[rq.Truncated], fenceText.Replace(read))
	resp, _, err := rt.ChatWithin(ctx, model.Request{Agent: "section_check", Role: model.Critic, MaxTokens: 300, Temperature: &t,
		Messages: []model.Message{{Role: "system", Content: prompt(ctx, "section_check")}, {Role: "user", Content: user}}}, b)
	switch {
	case ctx.Err() != nil:
		return nil, "", ctx.Err()
	case errors.Is(err, agent.ErrBudget):
		return nil, "the call's grant could not fund it", nil
	case err != nil:
		return nil, "its model call failed", nil
	}
	answer, reason, ok := checkAnswer(resp.Text)
	if !ok {
		return nil, "it did not answer yes, no or unclear", nil
	}
	chk = &SectionCheck{Answer: answer, Reason: truncate(strings.Join(strings.Fields(strings.NewReplacer("⟦", "", "⟧", "").Replace(reason)), " "), 300), Truncated: rq.Truncated, Bytes: len(read)}
	if chk.Reason == "" {
		chk.Reason = "(no reason given)"
	}
	return chk, "", nil
}

// deviations turns check_deviation's verdicts into findings (G2 for both sides). A verdict's
// controlling quote must lie in the requirement's context (lab-r3 r2 verifier H3: any substring of
// the document passed, so a quote that dropped "Do NOT" stood as what the memo requires); one that
// restated its requirement instead of quoting it (restates) stands on the requirement. The finding
// quotes the controlling text in context, the verdict's words marked, and gives the part label and
// the correction as the analyst's words, never as the document's (verifier L8).
func (e *Engine) deviations(ctx context.Context, rt *agent.Runtime, c agent.Call, b *agent.Budget, res agent.Result, rq reqText) (hookResult, float64, error) {
	var in devInput
	_ = json.Unmarshal(c.Input, &in)
	var ans struct{ Verdicts []verdict }
	_ = json.Unmarshal(res.Output, &ans)
	out := hookResult{Findings: []map[string]any{}, Notes: []string{}}
	all, err := load[Finding](ctx, e, c.TaskID, kFinding)
	if err != nil {
		return out, 0, err
	}
	idx := docs.NewText(rq.Text)
	var conform []string
	for _, v := range ans.Verdicts {
		if v.Verdict == "conform" {
			conform = append(conform, v.Part)
		}
	}
	name := func(id string) string {
		if d, err := e.docs.Get(ctx, c.DocumentIDs, id); err == nil {
			return d.Name
		}
		return id
	}
	checked, ok := 0, 0
	for _, v := range ans.Verdicts {
		if v.Verdict == "conform" {
			continue
		}
		checked++
		v.Controlling.Quote = strings.NewReplacer("⟦", "", "⟧", "").Replace(v.Controlling.Quote)
		inCtx := false
		if id, err := e.docs.Resolve(ctx, c.DocumentIDs, v.Controlling.DocumentID); err == nil && id == rq.DocID {
			_, inCtx = within(idx, rq.Ctx, v.Controlling.Quote)
		}
		reason := ""
		if !inCtx {
			if restates(v.Controlling.Quote, rq.Joined()) { // restated, not quoted (bench: two real deviations dropped)
				out.Notes = append(out.Notes, fmt.Sprintf("the %s verdict on %q restated its requirement instead of quoting it: the requirement quoted from %s stands for it", v.Verdict, v.Part, rq.DocName))
				v.Controlling.Quote = rq.Joined()
			} else {
				reason = "its controlling quote is not in the requirement's passage in " + rq.DocName + " (the section that holds the requirement, as the subagent was sent it, and its heading path)"
			}
		}
		v.Controlling.DocumentID = rq.DocID
		shown := rq.Ctx // the controlling text the finding quotes: the requirement's section and heading path
		f := Finding{Finding: analysis.Finding{IssueID: in.IssueID}, Severity: strings.ToLower(v.Severity), Arm: agent.Arm{Tool: "check_deviation", Model: res.Model}}
		for _, p := range shown {
			cit, err := e.verify(ctx, nil, c, b, "check_deviation", quoteOf(rq.DocID, rq.Text[p.s:p.e]))
			if err != nil {
				return out, 0, err
			}
			f.Citations = append(f.Citations, cit)
		}
		ground := renderContext(rq.Text, shown, nil, "\n")
		switch {
		case reason != "":
		case !slices.Contains(in.ReviewedDocIDs, v.Document):
			reason = "it names a document outside the request's reviewed documents"
		case v.Verdict == "deviate":
			rev, err := e.verify(ctx, nil, c, b, "check_deviation", quoteOf(v.Document, deref(v.Reviewed)))
			if err != nil {
				return out, 0, err
			}
			f.Citations = append(f.Citations, rev)
			ground += "\n" + deref(v.Reviewed)
			if rev.Method == "none" {
				reason = "its reviewed quote is not in " + name(v.Document)
			} else if conformsRe.MatchString(v.Correction) {
				reason = "it says the document conforms"
			}
		default: // omitted: the provision must not verify in that document (bench: a word count dropped eight real omissions)
			if here, err := e.present(ctx, rt, c, b, v.Document, v.Controlling.Quote); err != nil {
				return out, 0, err
			} else if here {
				reason = "the provision is present in " + name(v.Document)
			} else if r := deref(v.Reviewed); r != "" { // the passage where it belongs, when it verifies
				if rev, err := e.verify(ctx, nil, c, b, "check_deviation", quoteOf(v.Document, r)); err != nil {
					return out, 0, err
				} else if rev.Method != "none" {
					f.Citations, ground = append(f.Citations, rev), ground+"\n"+r
				} else {
					v.Reviewed = nil
				}
			}
		}
		if reason == "" && slices.ContainsFunc(f.Citations, func(x Citation) bool { return x.Method == "none" }) {
			reason = "its controlling text did not verify"
		}
		f.Check = rq.Check // the requirement's own check, made before the subagent ran (checkSection)
		if reason != "" {
			out.Dropped++
			out.Notes = append(out.Notes, "dropped the "+v.Verdict+" verdict on "+fmt.Sprintf("%q", v.Part)+": "+reason)
			continue
		}
		ok++
		corr := v.Correction
		if bad := Untraced(corr, ground, true); len(bad) > 0 || strings.TrimSpace(corr) == "" {
			corr = "[model correction withheld: it states a figure the quotes do not] " + genericCorrection
		}
		label := map[string]string{"deviate": "DEVIATION", "omitted": "OMISSION"}[v.Verdict]
		under := ""
		if rq.Path != "" {
			under = ", under the headings " + rq.Path
		}
		f.Claim = fmt.Sprintf("%s (%s): %s %s the controlling source, %s, whose text around the requirement reads%s (the requirement marked ⟦ ⟧): “%s”", label, v.Severity, name(v.Document),
			map[bool]string{true: "omits a provision required by", false: "deviates from"}[v.Verdict == "omitted"], rq.DocName, under, renderContext(rq.Text, shown, rq.marks(), " / "))
		if v.Verdict == "deviate" {
			f.Claim += fmt.Sprintf("; it reads “%s”", deref(v.Reviewed))
		} else if deref(v.Reviewed) != "" {
			f.Claim += fmt.Sprintf("; the closest provision reads “%s”", deref(v.Reviewed))
		}
		f.Claim += ". The analyst's reading (not a quotation; check it against the controlling text above): " + strings.TrimRight(v.Part, ". ") + ". The analyst's correction (not a quotation): " + corr
		if len(conform) > 0 {
			f.Claim += " The analyst found the requirement implemented only in part (conforming: " + strings.Join(conform, "; ") + ")."
		}
		if f.Check == nil {
			f.Low = true
			f.Claim += fmt.Sprintf(" The independent check of whether %s imposes the requirement as quoted did not run (%s): low confidence, for a lawyer's review.", rq.DocName, rq.CheckWhy)
		} else if f.Low = f.Check.Answer != "yes" || f.Check.Truncated; f.Low {
			how := "could not tell"
			if f.Check.Answer == "yes" {
				how = "found that it imposes the requirement as quoted, but that text begins after the requirement's sentence, paragraph or list does, or cuts a sentence"
			} else if f.Check.Truncated {
				how += "; that text begins after the requirement's sentence, paragraph or list does, or cuts a sentence"
			}
			f.Claim += fmt.Sprintf(" An independent check read the surrounding text (%d bytes) and %s: low confidence, for a lawyer's review. The checker's reasoning (not a quotation): %s", f.Check.Bytes, how, f.Check.Reason)
		} else {
			f.Claim += fmt.Sprintf(" An independent check read the surrounding text (%d bytes) and found that it imposes the requirement as quoted. The checker's reasoning (not a quotation): %s", f.Check.Bytes, f.Check.Reason)
		}
		for _, x := range f.Citations {
			f.Quotes = append(f.Quotes, analysis.Quote{DocumentID: x.DocumentID, Quote: x.Quote, Locator: x.Locator})
		}
		f.Verified = true
		f.FID = nextID("F", len(all))
		all = append(all, f)
		if err := e.write(ctx, c.TaskID, kFinding, f.FID, f, false); err != nil {
			return out, 0, err
		}
		out.Findings = append(out.Findings, admitted(f))
	}
	if checked == 0 {
		return out, 1, nil
	}
	return out, float64(ok) / float64(checked), nil
}

func (h hooked) Spec() agent.Spec {
	s := h.Tool.Spec()
	if s.Name == "check_deviation" { // its grant holds the requirement's check beside the subagent's own turns
		s.MaxTurns++
	}
	s.MaxTurns += goTurns(s.Name)
	if s.Name == "draft_section" {
		s.Out = json.RawMessage(`{"type":"object","additionalProperties":false,"required":["issueId","version","words"],"properties":{"issueId":{"type":"string"},"version":{"type":"integer"},"words":{"type":"integer"}}}`)
	} else {
		s.Out = hookOut
	}
	return s
}

func (h hooked) Call(ctx context.Context, c agent.Call) (agent.Result, error) {
	name := h.Tool.Spec().Name
	orig := c.Input // what the caller sent (after_call's rules read it)
	var in map[string]any
	_ = json.Unmarshal(c.Input, &in)
	str := func(k string) string { s, _ := in[k].(string); return s }
	var draft draftReq
	var rq reqText
	var preUse agent.Usage // spent before the subagent ran (check_deviation's requirement check)
	var held agent.Grant   // kept from the subagent for Go's calls after it (draft_section's figure reader)
	switch name {
	case "extract_facts":
		if str("issueId") == "" { // the plan's issues: each finding names the one it bears on (bench5 SEC: 896 findings, most on none)
			issues, err := load[Issue](ctx, h.e, c.TaskID, kIssue)
			if err != nil {
				return agent.Result{}, err
			}
			only, part := ctx.Value(issuesKey{}).([]string) // a page read again for the issues added since: only those
			var list []map[string]string
			for _, is := range issues {
				if !part || slices.Contains(only, is.ID) {
					list = append(list, map[string]string{"id": is.ID, "question": is.Question})
				}
			}
			if len(list) > 0 {
				in["issues"] = list
			}
		}
		if str("documentId") != "" && str("sectionId") != "" {
			off, _ := in["offset"].(float64)
			if str("through") != "" {
				text, ok := h.e.runText(ctx, c.DocumentIDs, str("documentId"), str("sectionId"), str("through"))
				if !ok || off != 0 {
					return agent.Result{}, agent.Fail(fmt.Sprintf("extract_facts: through must be a top-level section at or after sectionId, the run at most %d tokens, with offset 0 or null", docs.MaxSectionTokens))
				}
				in["sectionText"], in["truncated"], in["next"] = text, false, 0
			} else if p, err := h.e.docs.Section(ctx, c.DocumentIDs, str("documentId"), str("sectionId"), int(off), sweepTokens); err == nil {
				in["sectionText"], in["truncated"], in["next"] = p.Text, p.Truncated, p.Next
				if p.Header != "" { // a later page of a table: its columns, by reference to the header row
					in["header"] = p.Header
				}
			}
		}
	case "analyze_issue":
		for _, p := range packsFor(ctx, str("jurisdiction"), "") {
			in["packText"] = str("packText") + "\n\n" + p.Body
		}
	case "check_deviation":
		var err error
		if rq, err = h.e.quotedRequirement(ctx, c); err != nil {
			return agent.Result{}, err
		}
		in["requirement"] = rq.Joined()
		in["requirementContext"] = rq.Context()                                // what it judges against: the requirement with what governs it
		var su agent.Usage                                                     // the passages' query embedding, metered (lab-r4 verifier L3)
		in["reviewedPassages"], su = h.e.reviewedPassages(ctx, c, rq.Joined()) // bench4, trust: every call spent its five turns searching and checking quotes
		pre := agent.NewBudget(c.Budget.Calls, max(0, c.Budget.USD-su.USD), 0) // the requirement's check comes out of the grant first (bench5: unfunded checks dropped real deviations)
		if rq.Check, rq.CheckWhy, err = h.e.checkSection(ctx, h.rt, pre, rq); err != nil {
			u := pre.Spent()
			u.Add(su)
			return agent.Result{Usage: u}, err
		}
		preUse = pre.Spent()
		preUse.Add(su)
		c.Budget = agent.Grant{Calls: max(0, c.Budget.Calls-preUse.Calls), USD: max(0, c.Budget.USD-preUse.USD)}
		if rq.Check != nil && rq.Check.Answer == "no" { // nothing to compare with: the document does not require it
			return agent.Result{Usage: preUse}, agent.Fail(fmt.Sprintf("check_deviation: an independent reading of %s around the requirement found that it does not impose the requirement as quoted (negated or overridden): %s. Quote the requirement together with what governs it (its lead-in, exception or override), as the document states what it requires, and call again",
				rq.DocName, fenceText.Replace(rq.Check.Reason)))
		}
	case "draft_section":
		var err error
		if draft, err = h.e.draftRequest(ctx, c.TaskID, c.DocumentIDs, str("issueId"), c.Input); err != nil {
			return agent.Result{}, err
		}
		in = draft.request
	}
	if r := readerReserve(ctx, h.rt); goTurns(name) > 0 && ctx.Value(readQueueKey{}) == nil && c.Budget.Calls > r.Calls && (r.USD == 0 || c.Budget.USD > r.USD) { // the figure reader of its answer, held back from the subagent (lab-r4 r5 L4); a sweep's visit reads nothing itself (readFindings)
		held, c.Budget = r, agent.Grant{Calls: c.Budget.Calls - r.Calls, USD: c.Budget.USD - r.USD}
	}
	c.Input, _ = json.Marshal(in)
	res, err := h.Tool.Call(ctx, c)
	res.Usage.Add(preUse)
	if err == nil {
		err = awaitTurn(ctx) // a parallel sweep's visit admits in plan order
	}
	if err != nil {
		return res, err
	}
	b := agent.NewBudget(c.Budget.Calls-res.Usage.Calls+preUse.Calls+held.Calls, c.Budget.USD-res.Usage.USD+preUse.USD+held.USD, 0) // c.Budget is already net of preUse and held
	// after_call's rules on the subagent's own answer, before Go records anything from it (#58 r1 H1):
	// blocked, nothing is admitted or saved and the answer is withheld; a sweep's visit is still done
	if v, err := afterHooked(ctx, h.rt, c, name, orig, res.Output, b); err != nil {
		res.Usage.Add(b.Spent())
		return res, err
	} else if v.blocked != "" {
		res.Usage.Add(b.Spent())
		if name == "draft_section" {
			return agent.Result{Usage: res.Usage, Model: res.Model}, agent.Fail("draft_section's draft was withheld and not saved: " + v.blocked)
		}
		out, _ := json.Marshal(hookResult{Findings: []map[string]any{}, Notes: []string{"withheld, nothing admitted: " + v.blocked}})
		return agent.Result{Output: out, Usage: res.Usage, Model: res.Model}, nil
	}
	var out any
	var reward float64
	switch name {
	case "draft_section":
		out, err = h.e.saveSection(ctx, h.rt, c, b, draft, res.Output)
		reward = 1
	case "check_deviation":
		out, reward, err = h.e.deviations(ctx, h.rt, c, b, res, rq)
	default:
		var ans struct {
			Findings                      []draftFinding
			Gaps                          []string
			Rule, Application, Conclusion string
			Authorities                   []struct {
				Cite     string
				InRecord bool
			}
		}
		_ = json.Unmarshal(res.Output, &ans)
		notes := slices.Clone(ans.Gaps)
		for k, v := range map[string]string{"rule": ans.Rule, "application": ans.Application, "conclusion": ans.Conclusion} {
			if v != "" {
				notes = append(notes, k+": "+v)
			}
		}
		slices.Sort(notes)
		for _, a := range ans.Authorities {
			if !a.InRecord {
				notes = append(notes, "authority not in the record (flagged if cited): "+a.Cite)
			}
		}
		out, reward, err = h.e.admit(ctx, h.rt, c, b, held, name, str("issueId"), res.Model, ans.Findings, notes)
		if err == nil && name == "analyze_issue" && strings.TrimSpace(ans.Conclusion) != "" && str("issueId") != "" { // for the issue's drafter (cover.go)
			err = h.e.write(ctx, c.TaskID, kAnalysis, str("issueId"), Analysis{truncate(ans.Rule, 1500), truncate(ans.Application, 3000), truncate(ans.Conclusion, 1000)}, true)
		}
	}
	res.Usage.Add(b.Spent())
	if err != nil {
		return res, err
	}
	res.Output, _ = json.Marshal(out)
	res.Reward = &reward
	return res, nil
}

// draftRequest completes a draft_section call (paged drafting): the issue, its named findings
// (verified and not rejected only: G3), their figure handles and every worksheet's, the summaries
// of the sections already written, in plan order, and on a redraft the checks the current version
// fails (lint), so the drafter fixes exactly those.
func (e *Engine) draftRequest(ctx context.Context, taskID string, scope []string, issueID string, input json.RawMessage) (draftReq, error) {
	var in struct {
		FIDs   []string `json:"fids"`
		Revise *string
	}
	_ = json.Unmarshal(input, &in)
	issues, err := load[Issue](ctx, e, taskID, kIssue)
	secs, serr := load[Section](ctx, e, taskID, kSection)
	use, uerr := e.usable(ctx, taskID)
	if err = cmpErr(err, serr, uerr); err != nil {
		return draftReq{}, err
	}
	i := slices.IndexFunc(issues, func(is Issue) bool { return is.ID == issueID })
	if i < 0 {
		return draftReq{}, agent.Fail("draft_section: " + issueID + " is not a plan issue; draft one of the plan's issues (ledger op findings lists them)")
	}
	var fs []map[string]any
	var omitted []string
	names := map[string]string{} // documentId → its name, so the drafter can say which document states what
	name := func(id string) string {
		if _, ok := names[id]; !ok {
			if d, err := e.docs.Get(ctx, scope, id); err == nil {
				names[id] = d.Name
			} else {
				names[id] = ""
			}
		}
		return names[id]
	}
	for _, id := range in.FIDs {
		j := slices.IndexFunc(use, func(f Finding) bool { return f.FID == id })
		if j < 0 {
			omitted = append(omitted, id)
			continue
		}
		var qs []map[string]string
		for _, c := range use[j].Citations {
			qs = append(qs, map[string]string{"documentId": c.DocumentID, "document": name(c.DocumentID), "quote": c.Quote, "locator": c.Locator})
		}
		fs = append(fs, map[string]any{"fid": id, "claim": use[j].Claim, "quotes": qs})
	}
	if len(fs) == 0 {
		return draftReq{}, agent.Fail("draft_section: none of fids is a verified finding of this task; name verified findings (ledger op findings)")
	}
	d := draftReq{issueID: issueID}
	all, err := e.handleSet(ctx, taskID, use)
	if err != nil {
		return draftReq{}, err
	}
	hs := []map[string]string{}
	for _, h := range all { // the drafter sees its findings' handles and every worksheet's; Go substitutes the run's set
		d.figs = append(d.figs, Fig{h.Handle, h.FID, h.Value})
		if h.FID == "" || slices.Contains(in.FIDs, h.FID) {
			hs = append(hs, map[string]string{"handle": h.Handle, "fid": cmpStr(h.FID != "", h.FID, "worksheet "+h.Ref), "label": h.Label})
		}
	}
	var prior []map[string]string
	for _, is := range issues {
		if k := slices.IndexFunc(secs, func(s Section) bool { return s.IssueID == is.ID }); k >= 0 && is.ID != issueID {
			prior = append(prior, map[string]string{"issueId": is.ID, "summary": secs[k].Summary})
		}
	}
	d.request = map[string]any{"issue": map[string]string{"id": issueID, "question": issues[i].Question}, "findings": fs, "handles": hs,
		"priorSections": prior, "revise": in.Revise}
	if as, err := e.analyses(ctx, taskID); err != nil {
		return draftReq{}, err
	} else if a, ok := as[issueID]; ok {
		d.request["analysis"] = a // the issue's legal analysis (analyze_issue): rule, application, conclusion
	}
	if len(omitted) > 0 {
		d.request["omitted"] = "not verified findings of this task, so not shown: " + strings.Join(omitted, ", ")
	}
	if k := slices.IndexFunc(secs, func(s Section) bool { return s.IssueID == issueID }); k >= 0 {
		ws, err := e.worksheets(ctx, taskID)
		if err != nil {
			return draftReq{}, err
		}
		byFID := map[string]Finding{}
		for _, f := range use {
			byFID[f.FID] = f
		}
		if checks := lint(issueID, secs[k], byFID, ws); len(checks) > 0 {
			d.request["checks"] = checks
		}
	}
	return d, nil
}

// saveSection records a drafted section with the handle set its drafter was given; the draft's
// version moves on.
func (e *Engine) saveSection(ctx context.Context, rt *agent.Runtime, c agent.Call, b *agent.Budget, d draftReq, answer json.RawMessage) (any, error) {
	taskID := c.TaskID
	var a struct{ Markdown, Summary string }
	_ = json.Unmarshal(answer, &a)
	secs, err := load[Section](ctx, e, taskID, kSection)
	if err != nil {
		return nil, err
	}
	s := Section{IssueID: d.issueID, Markdown: splitCites(a.Markdown), Summary: splitCites(a.Summary), Handles: d.figs, Version: version(secs) + 1}
	before := b.Spent().Calls
	if err := e.readSection(ctx, rt, c, b, &s); err != nil {
		return nil, err
	}
	if n := b.Spent().Calls - before; n > 0 && ctx.Value(coverDraft{}) == nil { // the reader's calls are not the lead's drafter's: P4's draft share leaves them out (policy.go); a coverage redraft's are its finish step's
		prior, err := load[int](ctx, e, taskID, kRead)
		if err != nil {
			return nil, err
		}
		for _, p := range prior {
			n += p
		}
		if err := e.write(ctx, taskID, kRead, "draft", n, true); err != nil {
			return nil, err
		}
	}
	if err := e.write(ctx, taskID, kSection, d.issueID, s, true); err != nil {
		return nil, err
	}
	return map[string]any{"issueId": d.issueID, "version": s.Version, "words": len(strings.Fields(a.Markdown))}, nil
}

// goTurns are the calls Go makes after a hooked subagent out of its grant, held back from it: the
// figure reader of a drafted section or of an evidence call's findings (lab-r4 r5 L4: reserved before
// the subagent runs, and from the quotes' judges, never what they left). They are not the
// subagent's turns: P4's class share does not count them against the subagent.
func goTurns(name string) int {
	if name == "draft_section" || name == "extract_facts" || name == "analyze_issue" {
		return 1
	}
	return 0
}

func (h hooked) Spec() agent.Spec {
	s := h.Tool.Spec()
	if s.Name == "check_deviation" { // its grant holds the requirement's check beside the subagent's own turns
		s.MaxTurns++
	}
	s.MaxTurns += goTurns(s.Name)
	if s.Name == "draft_section" {
		s.Out = json.RawMessage(`{"type":"object","additionalProperties":false,"required":["issueId","version","words"],"properties":{"issueId":{"type":"string"},"version":{"type":"integer"},"words":{"type":"integer"}}}`)
	} else {
		s.Out = hookOut
	}
	return s
}

func (h hooked) Call(ctx context.Context, c agent.Call) (agent.Result, error) {
	name := h.Tool.Spec().Name
	orig := c.Input // what the caller sent (after_call's rules read it)
	var in map[string]any
	_ = json.Unmarshal(c.Input, &in)
	str := func(k string) string { s, _ := in[k].(string); return s }
	var draft draftReq
	var rq reqText
	var preUse agent.Usage // spent before the subagent ran (check_deviation's requirement check)
	var held agent.Grant   // kept from the subagent for Go's calls after it (draft_section's figure reader)
	switch name {
	case "extract_facts":
		if str("issueId") == "" { // the plan's issues: each finding names the one it bears on (bench5 SEC: 896 findings, most on none)
			issues, err := load[Issue](ctx, h.e, c.TaskID, kIssue)
			if err != nil {
				return agent.Result{}, err
			}
			only, part := ctx.Value(issuesKey{}).([]string) // a page read again for the issues added since: only those
			var list []map[string]string
			for _, is := range issues {
				if !part || slices.Contains(only, is.ID) {
					list = append(list, map[string]string{"id": is.ID, "question": is.Question})
				}
			}
			if len(list) > 0 {
				in["issues"] = list
			}
		}
		if str("documentId") != "" && str("sectionId") != "" {
			off, _ := in["offset"].(float64)
			if str("through") != "" {
				text, ok := h.e.runText(ctx, c.DocumentIDs, str("documentId"), str("sectionId"), str("through"))
				if !ok || off != 0 {
					return agent.Result{}, agent.Fail(fmt.Sprintf("extract_facts: through must be a top-level section at or after sectionId, the run at most %d tokens, with offset 0 or null", docs.MaxSectionTokens))
				}
				in["sectionText"], in["truncated"], in["next"] = text, false, 0
			} else if p, err := h.e.docs.Section(ctx, c.DocumentIDs, str("documentId"), str("sectionId"), int(off), sweepTokens); err == nil {
				in["sectionText"], in["truncated"], in["next"] = p.Text, p.Truncated, p.Next
				if p.Header != "" { // a later page of a table: its columns, by reference to the header row
					in["header"] = p.Header
				}
			}
		}
	case "analyze_issue":
		for _, p := range packsFor(ctx, str("jurisdiction"), "") {
			in["packText"] = str("packText") + "\n\n" + p.Body
		}
	case "check_deviation":
		var err error
		if rq, err = h.e.quotedRequirement(ctx, c); err != nil {
			return agent.Result{}, err
		}
		in["requirement"] = rq.Joined()
		in["requirementContext"] = rq.Context()                                // what it judges against: the requirement with what governs it
		var su agent.Usage                                                     // the passages' query embedding, metered (lab-r4 verifier L3)
		in["reviewedPassages"], su = h.e.reviewedPassages(ctx, c, rq.Joined()) // bench4, trust: every call spent its five turns searching and checking quotes
		pre := agent.NewBudget(c.Budget.Calls, max(0, c.Budget.USD-su.USD), 0) // the requirement's check comes out of the grant first (bench5: unfunded checks dropped real deviations)
		if rq.Check, rq.CheckWhy, err = h.e.checkSection(ctx, h.rt, pre, rq); err != nil {
			u := pre.Spent()
			u.Add(su)
			return agent.Result{Usage: u}, err
		}
		preUse = pre.Spent()
		preUse.Add(su)
		c.Budget = agent.Grant{Calls: max(0, c.Budget.Calls-preUse.Calls), USD: max(0, c.Budget.USD-preUse.USD)}
		if rq.Check != nil && rq.Check.Answer == "no" { // nothing to compare with: the document does not require it
			return agent.Result{Usage: preUse}, agent.Fail(fmt.Sprintf("check_deviation: an independent reading of %s around the requirement found that it does not impose the requirement as quoted (negated or overridden): %s. Quote the requirement together with what governs it (its lead-in, exception or override), as the document states what it requires, and call again",
				rq.DocName, fenceText.Replace(rq.Check.Reason)))
		}
	case "draft_section":
		var err error
		if draft, err = h.e.draftRequest(ctx, c.TaskID, c.DocumentIDs, str("issueId"), c.Input); err != nil {
			return agent.Result{}, err
		}
		in = draft.request
	}
	if r := readerReserve(ctx, h.rt); goTurns(name) > 0 && ctx.Value(readQueueKey{}) == nil && c.Budget.Calls > r.Calls && (r.USD == 0 || c.Budget.USD > r.USD) { // the figure reader of its answer, held back from the subagent (lab-r4 r5 L4); a sweep's visit reads nothing itself (readFindings)
		held, c.Budget = r, agent.Grant{Calls: c.Budget.Calls - r.Calls, USD: c.Budget.USD - r.USD}
	}
	c.Input, _ = json.Marshal(in)
	res, err := h.Tool.Call(ctx, c)
	res.Usage.Add(preUse)
	if err == nil {
		err = awaitTurn(ctx) // a parallel sweep's visit admits in plan order
	}
	if err != nil {
		return res, err
	}
	b := agent.NewBudget(c.Budget.Calls-res.Usage.Calls+preUse.Calls+held.Calls, c.Budget.USD-res.Usage.USD+preUse.USD+held.USD, 0) // c.Budget is already net of preUse and held
	// after_call's rules on the subagent's own answer, before Go records anything from it (#58 r1 H1):
	// blocked, nothing is admitted or saved and the answer is withheld; a sweep's visit is still done
	if v, err := afterHooked(ctx, h.rt, c, name, orig, res.Output, b); err != nil {
		res.Usage.Add(b.Spent())
		return res, err
	} else if v.blocked != "" {
		res.Usage.Add(b.Spent())
		if name == "draft_section" {
			return agent.Result{Usage: res.Usage, Model: res.Model}, agent.Fail("draft_section's draft was withheld and not saved: " + v.blocked)
		}
		out, _ := json.Marshal(hookResult{Findings: []map[string]any{}, Notes: []string{"withheld, nothing admitted: " + v.blocked}})
		return agent.Result{Output: out, Usage: res.Usage, Model: res.Model}, nil
	}
	var out any
	var reward float64
	switch name {
	case "draft_section":
		out, err = h.e.saveSection(ctx, h.rt, c, b, draft, res.Output)
		reward = 1
	case "check_deviation":
		out, reward, err = h.e.deviations(ctx, h.rt, c, b, res, rq)
	default:
		var ans struct {
			Findings                      []draftFinding
			Gaps                          []string
			Rule, Application, Conclusion string
			Authorities                   []struct {
				Cite     string
				InRecord bool
			}
		}
		_ = json.Unmarshal(res.Output, &ans)
		notes := slices.Clone(ans.Gaps)
		for k, v := range map[string]string{"rule": ans.Rule, "application": ans.Application, "conclusion": ans.Conclusion} {
			if v != "" {
				notes = append(notes, k+": "+v)
			}
		}
		slices.Sort(notes)
		for _, a := range ans.Authorities {
			if !a.InRecord {
				notes = append(notes, "authority not in the record (flagged if cited): "+a.Cite)
			}
		}
		out, reward, err = h.e.admit(ctx, h.rt, c, b, held, name, str("issueId"), res.Model, ans.Findings, notes)
		if err == nil && name == "analyze_issue" && strings.TrimSpace(ans.Conclusion) != "" && str("issueId") != "" { // for the issue's drafter (cover.go)
			err = h.e.write(ctx, c.TaskID, kAnalysis, str("issueId"), Analysis{truncate(ans.Rule, 1500), truncate(ans.Application, 3000), truncate(ans.Conclusion, 1000)}, true)
		}
	}
	res.Usage.Add(b.Spent())
	if err != nil {
		return res, err
	}
	res.Output, _ = json.Marshal(out)
	res.Reward = &reward
	return res, nil
}

// admit checks a subagent's findings and records them (G2): every quote through the ladder (the
// finding verifies only when all of them do; otherwise it is quarantined), each value kept only
// when its own quote states it, each relation typed by BELO-lite, near-duplicates merged into the
// first. The reward is the share of quotes that verified.
func (e *Engine) admit(ctx context.Context, rt *agent.Runtime, c agent.Call, b *agent.Budget, reserve agent.Grant, tool, issueID, model string, drafts []draftFinding, notes []string) (hookResult, float64, error) {
	out := hookResult{Findings: []map[string]any{}, Notes: append([]string{}, notes...)}
	all, err := load[Finding](ctx, e, c.TaskID, kFinding)
	if err != nil {
		return out, 0, err
	}
	var plan []Issue
	if tool == "extract_facts" && issueID == "" {
		if plan, err = load[Issue](ctx, e, c.TaskID, kIssue); err != nil {
			return out, 0, err
		}
	}
	scoped := len(plan) > 0
	if only, ok := ctx.Value(issuesKey{}).([]string); ok && scoped { // a page read again: the issues added since
		plan = slices.DeleteFunc(plan, func(is Issue) bool { return !slices.Contains(only, is.ID) })
	}
	quotes, ok, off := 0, 0, 0
	type pending struct {
		f    Finding
		d    draftFinding
		text string
		it   *reading
	}
	var pend []pending
	// the quotes' judges spend all but the figure reader's reserve (lab-r4 r5 L4: the reader is never
	// what they left), unless no finding states a number, when the reader makes no call (r7 L4)
	queue, deferred := ctx.Value(readQueueKey{}).(*readQueue) // a sweep reads its findings together at its end
	numbers := !deferred && slices.ContainsFunc(drafts, func(d draftFinding) bool {
		return len(d.Values) > 0 && len(findingReading(Finding{Finding: analysis.Finding{Claim: d.Claim, Entities: d.Entities}}, d.Quotes, d.Values).ps) > 0
	})
	vb := b
	if rc, ru := b.Remaining(); numbers && reserve.Calls > 0 && rc > reserve.Calls {
		if g, err := b.Grant(rc-reserve.Calls, max(0, ru-reserve.USD), agent.LevelWork); err == nil {
			vb = g
			defer g.Close()
		}
	}
	for _, d := range drafts {
		fi := issueID
		if scoped { // a fact on none of the plan's issues is not admitted
			if fi = deref(d.IssueID); !slices.ContainsFunc(plan, func(is Issue) bool { return is.ID == fi }) {
				off++
				continue
			}
		}
		f := Finding{Finding: analysis.Finding{IssueID: fi, Claim: strings.TrimSpace(d.Claim), Quotes: d.Quotes, Entities: d.Entities}, Severity: "medium", Arm: agent.Arm{Tool: tool, Model: model}}
		var text strings.Builder
		var vq []analysis.Quote
		for _, q := range d.Quotes {
			cit, err := e.verify(ctx, rt, c, vb, tool, q)
			if err != nil {
				return out, 0, err
			}
			f.Citations = append(f.Citations, cit)
			quotes++
			if cit.Method != "none" {
				ok++
				text.WriteString(q.Quote + "\n")
				vq = append(vq, analysis.Quote{DocumentID: cit.DocumentID, Quote: q.Quote, Locator: q.Locator})
			}
		}
		f.Verified = len(f.Citations) > 0 && !slices.ContainsFunc(f.Citations, func(c Citation) bool { return c.Method == "none" })
		pend = append(pend, pending{f, d, text.String(), findingReading(f, vq, d.Values)})
	}
	if vb != b {
		vb.Close() // its unspent part back to the call's grant, for the reader
	}
	var items []*reading // one figure reading for the call's findings (cached by content), out of the call's grant
	for _, p := range pend {
		if len(p.text) > 0 && !deferred && len(p.d.Values) > 0 { // a finding with no typed value is read when a section cites it
			items = append(items, p.it)
		}
	}
	if err := e.readFigures(ctx, rt, c, b, tool, items); err != nil {
		return out, 0, err
	}
	for _, p := range pend {
		f, d := p.f, p.d
		if len(p.text) > 0 && (deferred || len(d.Values) == 0) {
			f.Values, f.Unread = d.Values, true // read later: by the sweep at its end, or when a section cites it
		} else {
			applyReading(&f, d.Values, p.it, p.text)
		}
		f.Relations, _ = analysis.Relations(d.Entities, d.Relations)
		if i := slices.IndexFunc(all, func(x Finding) bool {
			return x.ok() && f.ok() && restated(x, f)
		}); i >= 0 {
			for _, c := range f.Citations {
				if !slices.ContainsFunc(all[i].Citations, func(x Citation) bool { return x.DocumentID == c.DocumentID && x.Quote == c.Quote }) {
					all[i].Citations = append(all[i].Citations, c)
					all[i].Quotes = append(all[i].Quotes, analysis.Quote{DocumentID: c.DocumentID, Quote: c.Quote, Locator: c.Locator})
				}
			}
			for _, n := range f.ValueNotes { // the duplicate's dropped values are the kept finding's (shown with it, disclosed)
				if !slices.Contains(all[i].ValueNotes, n) {
					all[i].ValueNotes = append(all[i].ValueNotes, n)
				}
			}
			if err := e.write(ctx, c.TaskID, kFinding, all[i].FID, all[i], true); err != nil {
				return out, 0, err
			}
			out.Notes = append(out.Notes, "merged into "+all[i].FID+" (an exact duplicate): "+f.Claim)
			for _, n := range f.ValueNotes {
				out.Notes = append(out.Notes, all[i].FID+": "+n)
			}
			continue
		}
		if h, ok := rt.Hooks.(hookRunner); ok { // finding_admitted's rules: quarantine, gate or annotate it
			if _, err := h.findingHooks(ctx, c, b, &f); err != nil {
				return out, 0, err
			}
		}
		f.FID = nextID("F", len(all))
		all = append(all, f)
		if deferred && f.Unread && len(f.Values) > 0 {
			queue.add(f.FID)
		}
		if err := e.write(ctx, c.TaskID, kFinding, f.FID, f, false); err != nil {
			return out, 0, err
		}
		out.Findings = append(out.Findings, admitted(f))
		for _, n := range f.ValueNotes {
			out.Notes = append(out.Notes, f.FID+": "+n)
		}
		if !f.Verified {
			out.Dropped++
		}
	}
	if off > 0 {
		out.Notes = append(out.Notes, fmt.Sprintf("dropped %d %s that named none of the plan's issues", off, plural(off, "finding", "findings")))
	}
	if quotes == 0 {
		return out, map[bool]float64{true: 1, false: 0}[len(drafts) == 0], nil
	}
	return out, float64(ok) / float64(quotes), nil
}

// applyReading sets a finding's readings from it (the reader's labels of its verified quotes, its
// typed values and its claim; text is its verified quotes): Figures, what G8 traces a memo figure
// citing it to; each of vals kept only when its quotes state it (valueStated: a value its quotes do
// not state is dropped, never silently, lab-r4 r3), and its claim's sums.
func applyReading(f *Finding, vals []analysis.Value, it *reading, text string) {
	rs, refused := it.readings()
	for _, n := range refused {
		f.ValueNotes = append(f.ValueNotes, "figure reader: "+n)
	}
	f.Figures, f.Values, f.Unread = quoteReadings(rs), nil, !it.read // a call that failed or went unfunded leaves it unread: read again when funded, counted until then (r1 MEDIUM-3)
	for j, v := range vals {
		fig, ok, low, why := valueStated(v, j, rs, text)
		if !ok {
			f.ValueNotes = append(f.ValueNotes, fmt.Sprintf("value %q (%s) not admitted: %s", v.Value, cmpStr(v.Metric != "", v.Metric, "no metric"), why))
			continue
		}
		v.Fig = fig
		if fig != nil && fig.Kind == analysis.KindMoney && v.Unit == "" && fig.Currency != "USD" && fig.Currency != "" {
			v.Unit = fig.Currency // the currency the reader read it in; "" is USD
		}
		if low { // admitted, gated for a lawyer: the reader could not read it with no doubt
			f.Low = true
			f.ValueNotes = append(f.ValueNotes, lowNote(v, fig))
		}
		f.Values = append(f.Values, v)
	}
	f.Values = append(f.Values, claimSums(f.Claim, rs, f.Values)...)
}

func (j aliasJoin) Call(ctx context.Context, c agent.Call) (agent.Result, error) {
	var in struct{ Aliases []analysis.Alias }
	_ = json.Unmarshal(c.Input, &in)
	if len(in.Aliases) > 0 { // the call itself uses its own and the run's
		was, err := load[analysis.Alias](ctx, j.e, c.TaskID, kAlias)
		if err != nil {
			return agent.Result{}, err
		}
		for _, a := range in.Aliases {
			key := strings.ToLower(norm(a.Name))
			if key == "" {
				continue
			}
			if i := slices.IndexFunc(was, func(x analysis.Alias) bool { return strings.ToLower(norm(x.Name)) == key }); i >= 0 {
				for _, o := range a.Aliases {
					if !slices.Contains(was[i].Aliases, o) {
						was[i].Aliases = append(was[i].Aliases, o)
					}
				}
				a = was[i]
			}
			if err := j.e.write(ctx, c.TaskID, kAlias, key, a, true); err != nil {
				return agent.Result{}, err
			}
		}
	}
	return j.Tool.Call(ctx, c)
}

func (s sheets) Call(ctx context.Context, c agent.Call) (agent.Result, error) {
	var in struct {
		Op         string
		FIDs       []string `json:"fids"`
		SalientTop int
	}
	if json.Unmarshal(c.Input, &in) == nil && in.Op == "handles" {
		use, err := s.e.usable(ctx, c.TaskID)
		hs, herr := s.e.handleSet(ctx, c.TaskID, use)
		if err = cmpErr(err, herr); err != nil {
			return agent.Result{}, err
		}
		hs = slices.DeleteFunc(hs, func(h analysis.Handle) bool {
			return h.FID == "" || len(in.FIDs) > 0 && !slices.Contains(in.FIDs, h.FID)
		})
		pg := agent.NewPage() // one page, saying truncated (bench6: the answer lacked the schema's truncated key)
		list := agent.Take(pg, append([]analysis.Handle{}, hs[:min(len(hs), cmp.Or(in.SalientTop, len(hs)))]...))
		out, _ := json.Marshal(map[string]any{"wid": nil, "result": nil, "unit": nil, "worksheet": nil, "literalOperands": nil, "tableMarkdown": nil,
			"handles": list, "truncated": pg.Truncated})
		return agent.Result{Output: out}, nil
	}
	res, err := s.Tool.Call(ctx, c)
	var w analysis.Worksheet
	if err == nil && json.Unmarshal(res.Output, &w) == nil && w.WID != "" {
		err = s.e.write(ctx, c.TaskID, kSheet, w.WID, w, false)
	}
	return res, err
}
